fun isValidExpense(amount: Double, category: String): Boolean {
    return amount > 0.0 && category.isNotBlank()
}

fun expenseSummary(category: String, amount: Double): String =
    "$category: £$amount"

fun main() {
    val amount = 14.25
    val category = "Food"

    if (isValidExpense(amount, category)) {
        println(expenseSummary(category, amount))
    } else {
        println("Invalid expense")
    }
}
